import PropTypes from 'prop-types';
import Draggable from 'react-draggable';
import './panel.scss';

/**
 * React компонент панели
 * @param {boolean} isOpened - Булев тип, определяющий видимость React компонента;
 * @param {object} style - Объект, стили панели;
 * @param {string} disableDraggble - Булев тип, отключает перетаскивание;
 */

function Panel({ children, isOpened, style, disableDraggble }) {
  return (
    <Draggable
      handle='.panel__move-handler'
      bounds='.workspace__content'
      defaultPosition={{ x: 12, y: 12 }}
      onStart={() => !disableDraggble}>
      <div style={style} className={`panel${isOpened ? ' panel_open' : ''}`}>
        <div
          className={`panel__move-handler panel__move-handler_position_top${disableDraggble ? ' panel__move-handler_inactive' : ''}`}>
          <div className='panel__handler-dot' />
          <div className='panel__handler-dot' />
          <div className='panel__handler-dot' />
        </div>
        <div
          className={`panel__move-handler panel__move-handler_position_bottom${disableDraggble ? ' panel__move-handler_inactive' : ''}`}>
          <div className='panel__handler-dot' />
          <div className='panel__handler-dot' />
          <div className='panel__handler-dot' />
        </div>
        <div className='panel__content'>{children}</div>
      </div>
    </Draggable>
  );
}

Panel.propTypes = {
  isOpened: PropTypes.bool,
  style: PropTypes.object,
  disableDraggble: PropTypes.bool,
};

export default Panel;
